<?php
require_once __DIR__.'/_guard.php'; require_platform_admin();
$status=(string)($_GET['status']??'all');$valid=['all','pending','success','failed'];if(!in_array($status,$valid,true))$status='all';
$sql='SELECT p.id,p.user_id,p.plan,p.amount_kobo,p.currency,p.reference,p.status,p.created_at,p.paid_at,u.business_name,u.email FROM subscription_payments p JOIN users u ON u.id=p.user_id';$args=[];if($status!=='all'){$sql.=' WHERE p.status=?';$args[]=$status;}$sql.=' ORDER BY p.id DESC LIMIT 500';$q=$pdo->prepare($sql);$q->execute($args);$rows=$q->fetchAll();
$revenue=(float)$pdo->query("SELECT COALESCE(SUM(amount_kobo),0)/100 FROM subscription_payments WHERE status='success'")->fetchColumn();
admin_page_start('Subscription payments');
?>
<div class="mb-4"><div class="text-uppercase small muted fw-semibold">BILLING</div><h1 class="h3 fw-bold mb-1">Subscription payments</h1><p class="muted mb-0">Verified subscription income only; business sales are not included.</p></div>
<div class="card p-4 mb-4"><div class="muted small">Lifetime verified subscription income</div><div class="stat"><?=money($revenue)?></div></div>
<div class="card p-3 mb-4"><form method="get" class="row g-2 align-items-end"><div class="col-md-4"><label class="form-label">Payment status</label><select class="form-select" name="status"><?php foreach(['all'=>'All','pending'=>'Pending','success'=>'Successful','failed'=>'Failed'] as $k=>$v):?><option value="<?=e($k)?>" <?=$status===$k?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="col-md-2 d-grid"><button class="btn btn-primary">Filter</button></div></form></div>
<div class="card p-3 p-md-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Business</th><th>Plan</th><th>Amount</th><th>Reference</th><th>Status</th><th>Created / paid</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['business_name'])?></strong><div class="small muted"><?=e($r['email'])?></div></td><td><?=e(ucfirst($r['plan']))?></td><td><?=money(((int)$r['amount_kobo'])/100)?></td><td><code><?=e($r['reference'])?></code></td><td><span class="badge text-bg-<?=$r['status']==='success'?'success':($r['status']==='failed'?'danger':'secondary')?>"><?=e(ucfirst($r['status']))?></span></td><td><?=e(date('d M Y H:i',strtotime($r['created_at'])))?><div class="small muted"><?=!empty($r['paid_at'])?'Paid '.e(date('d M Y H:i',strtotime($r['paid_at']))):''?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center muted py-4">No payment records found.</td></tr><?php endif;?></tbody></table></div><div class="small muted">Latest 500 payment attempts.</div></div>
<?php admin_page_end(); ?>
